(function(){
'use strict';
const data=window.LEARNING_DATA,C=window.StudyCore,KEY='boki-kotoba-progress-v1';
const app=document.getElementById('app');
if(!data?.cards?.length){app.innerHTML='<main class="workspace"><h1>教材を読み込めませんでした</h1><p>ページを再読み込みしてください。</p></main>';return;}
const byId=new Map(data.cards.map(c=>[c.id,c]));
const e=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const icons={home:'M3 11 12 3l9 8M5 10v10h5v-6h4v6h5V10',cards:'M6 5h13v16H6zM3 17V2h12',repeat:'M20 7v5h-5M4 17v-5h5M19 11a7 7 0 0 0-12-6L4 8m1 5a7 7 0 0 0 12 6l3-3',book:'M4 3h13a3 3 0 0 1 3 3v15H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3M6 17h14M7 7h9M7 11h7',arrow:'M5 12h14m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8',flame:'M12 3c2 5 7 6 7 12a7 7 0 0 1-14 0c0-4 3-6 4-8 0 3 2 4 2 4s3-3 1-8Z',shield:'m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6zM8 12l3 3 5-6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 7v7m0-11v1'};
function icon(name){return `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[name]||icons.book}"/></svg>`;}
let warning='',state;
try{state=C.clean(JSON.parse(localStorage.getItem(KEY)||'null'),new Set(byId.keys()));}catch{state=C.blank();warning='学習記録を読み込めませんでした。この画面では学習を続けられます。';}
let view='home',flash={ids:[],index:0,flipped:false,done:0,review:false},result=null,search='',category='all';
let shownDate=C.dayKey();
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{warning='このブラウザでは学習記録を保存できません。画面を閉じると今回の記録が失われる場合があります。';document.querySelector('#save-warning')?.replaceChildren(document.createTextNode(warning));document.querySelector('#save-warning')?.removeAttribute('hidden');}}
function selectedCards(){return data.cards.filter(c=>C.inGrade(c,state.grade));}
function activeCards(){return selectedCards().filter(c=>c.quizEligible!==false);}
function reviewCards(){return activeCards().filter(c=>C.weak(state.stats[c.id])||C.due(state.stats[c.id]));}
function gradeName(g=state.grade){return {'3':'3級','2':'2級','industrial':'工業簿記'}[g];}
function gradeHint(){return {'3':'まずは、基本の勘定科目から。','2':'3級の基礎と、2級で追加する科目を学習。','industrial':'原価の流れと、製造に使う科目を学習。'}[state.grade];}
function tags(c){return `<span class="tag">${e(c.category)}</span><span class="tag blue">${e({'借':'増加は借方','貸':'増加は貸方','両':'借貸は取引による','集計':'原価の集計・振替'}[c.side]||'取引による')}</span>${c.quizEligible===false?'<span class="tag gray">参考科目</span>':''}`;}
function badge(c){let s=state.stats[c.id];return C.mastered(s)?'<span class="tag">定着</span>':C.weak(s)?'<span class="tag orange">復習中</span>':s?'<span class="tag blue">学習中</span>':'<span class="tag gray">未学習</span>';}
function button(label,action,cls='primary',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function nav(label,key,symbol,n){return `<button data-action="nav" data-view="${key}" class="${view===key||(view==='quiz'&&key==='home')||(view==='results'&&key==='home')?'active':''}" ${view===key?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span>${n?`<span class="nav-count">${n}</span>`:''}</button>`;}
function shell(content){return `<div class="shell"><aside class="sidebar"><div class="brand-row"><div class="brand"><div class="brandmark" aria-hidden="true"><span>借</span><span>貸</span></div><strong>簿記ことば</strong></div><div class="mobile-about">${button('使い方','about','')}</div></div><p class="brand-caption">日商簿記 2級・3級</p><nav class="nav" aria-label="学習メニュー">${nav('今日の学習','home','home')}${nav('単語カード','cards','cards')}${nav('苦手の復習','review','repeat',reviewCards().length)}${nav('単語一覧','dictionary','book')}</nav><div class="sidebar-bottom"><p>1日10問。少しずつ、確実に。</p>${button('使い方・教材について','about','')}<p>学習記録はこのブラウザに保存</p></div></aside><main class="workspace" id="main"><header class="topbar"><div><span class="eyebrow">${e(gradeName())}の勘定科目</span><span class="date">　${new Date().toLocaleDateString('ja-JP',{month:'long',day:'numeric',weekday:'short'})}</span></div><div class="grade-switch" role="group" aria-label="級の切り替え">${['3','2','industrial'].map(g=>`<button data-action="grade" data-grade="${g}" class="${state.grade===g?'active':''}" aria-pressed="${state.grade===g}" ${view==='quiz'?'disabled':''}>${gradeName(g)}</button>`).join('')}</div></header><div id="save-warning" class="storage-warning" role="status" ${warning?'':'hidden'}>${e(warning)}</div>${content}</main></div><dialog id="dialog" aria-labelledby="dialog-title"></dialog><div id="announce" class="sr-only" aria-live="polite"></div>`;}
function head(title,description,tag=''){return `<div class="page-head"><div><h1 tabindex="-1">${e(title)}</h1><p>${e(description)}</p></div>${tag?`<span class="tag gray">${e(tag)}</span>`:''}</div>`;}
function home(){
 const cards=activeCards(),stats=cards.map(c=>state.stats[c.id]),learned=stats.filter(C.mastered).length,seen=stats.filter(v=>v?.seen).length,d=state.days[C.dayKey()]||{answered:0},review=reviewCards().length,session=state.sessions[state.grade];
 const teaser=cards.find(c=>!state.stats[c.id])||cards[0];
 const pairs=data.confusions.filter(p=>p.terms.every(id=>byId.has(id)&&C.inGrade(byId.get(id),state.grade))).slice(0,2);
 return head('今日も、ひとつずつ。',gradeHint(),`${cards.length}語を収録`)+`<div class="study-grid"><section class="panel daily-panel"><span class="eyebrow">DAILY PRACTICE</span><h2 class="daily-title">今日の10問</h2><p>意味・分類・借方と貸方。<br>思い出す練習で、使える知識に。</p><div class="daily-progress"><div class="track" role="progressbar" aria-label="今日の目標" aria-valuenow="${Math.min(d.answered,10)}" aria-valuemin="0" aria-valuemax="10"><span style="width:${Math.min(d.answered*10,100)}%"></span></div><span>${Math.min(d.answered,10)} / 10問</span></div>${button(`${session?`途中から続ける（${session.index+1}問目）`:d.answered>=10?'もう10問やってみる':'10問はじめる'} ${icon('arrow')}`,'quiz-start')}</section><section class="panel card-teaser"><div class="section-title"><span class="eyebrow">WORD CARD</span><span class="tag">${e(teaser.category)}</span></div><div class="teaser-term">${e(teaser.term)}</div><p class="subtle">意味と使う場面を思い出してみよう。</p><div class="button-row">${button(`単語カードをめくる ${icon('cards')}`,'open-card','secondary',`data-id="${teaser.id}"`)}</div></section></div><div class="stats"><div class="stat"><div class="stat-icon">${icon('book')}</div><div><div class="stat-number">${seen}<small>/ ${cards.length}語</small></div><div class="stat-label">学習した単語</div></div></div><div class="stat"><div class="stat-icon teal">${icon('check')}</div><div><div class="stat-number">${learned}<small>語</small></div><div class="stat-label">3回続けてできた</div></div></div><div class="stat"><div class="stat-icon orange">${icon('flame')}</div><div><div class="stat-number">${C.streakDays(state.days)}<small>日</small></div><div class="stat-label">続けて学習</div></div></div></div><div class="section-title"><h2>似ている科目を見分けよう</h2>${button(`すべて見る ${icon('chevron')}`,'all-confusions','text-button')}</div><div class="confusion">${pairs.map(p=>{const i=data.confusions.indexOf(p);return `<button class="panel" data-action="confusion" data-index="${i}"><span class="eyebrow">使い分け</span><h3>${e(byId.get(p.terms[0]).term)}<span class="pair-arrow">/</span>${e(byId.get(p.terms[1]).term)}</h3><p>${e(p.tip)}</p></button>`;}).join('')||`<div class="panel"><h3>材料 → 仕掛品 → 製品</h3><p class="subtle">原価がどの勘定へ移るか、単語カードで確認しよう。</p></div>`}</div><p class="study-note">${icon('shield')}記録はこのブラウザに保存されます。別の端末・ブラウザとは同期されません。</p>`;
}
function quiz(){const s=state.sessions[state.grade];if(!s)return empty('問題の準備ができていません','今日の学習からはじめてください。');const q=s.questions[s.index],answered=s.selected!==null,ok=answered&&s.selected===q.answer;
return `<div class="quiz-wrap">${head(s.mode==='review'?'苦手を、もう一度。':'今日の10問',`${gradeName()} · ${q.type}`)}<div class="quiz-progress"><span>${s.index+1} / ${s.questions.length}問</span><div class="track"><span style="width:${s.index/s.questions.length*100}%"></span></div><span>正解 ${s.results.filter(x=>x.correct).length}</span></div><section class="panel"><span class="tag blue">${e(q.type)}</span><h2 class="question">${e(q.prompt)}</h2><div class="choices">${q.options.map((o,i)=>`<button class="choice ${answered&&i===q.answer?'correct':answered&&i===s.selected?'incorrect':''}" data-action="answer" data-choice="${i}" data-index="${s.index}" data-card="${q.cardId}" ${answered?'disabled':''}><span>${i+1}</span>${e(o)}${answered&&i===q.answer?icon('check'):answered&&i===s.selected?icon('close'):''}</button>`).join('')}</div>${answered?`<div class="feedback ${ok?'':'bad'}" role="status"><h3>${ok?'正解！':'ここで覚えよう。'} ${!ok?`正解は「${e(q.options[q.answer])}」`:''}</h3><p>${e(q.explanation)}</p><div class="button-row">${button(s.index===s.questions.length-1?'結果を見る':'次の問題へ','next-question','primary',`data-index="${s.index}"`)}${button('この単語を確認','detail','text-button',`data-id="${q.cardId}"`)}</div></div>`:''}</section><div class="quiz-footer">${button('いったん戻る','nav','text-button','data-view="home"')}<small>途中の問題も自動保存されます。</small></div></div>`;
}
function empty(title,description,action='quiz-start',label='今日の10問へ'){return `<div class="panel empty">${icon('check')}<h2>${title}</h2><p>${description}</p>${button(label,action)}</div>`;}
function initFlash(id,review=false){let list=review?reviewCards():activeCards();if(id&&byId.has(id)&&!list.some(c=>c.id===id))list=[byId.get(id),...list];flash={ids:list.map(c=>c.id),index:Math.max(0,list.findIndex(c=>c.id===id)),flipped:false,done:0,review};view='cards';}
function cardsView(){if(!flash.ids.length)return head('単語カード','名前・意味・取引をつなげよう。')+empty('いま復習する単語はありません','「今日の10問」で、新しい科目を学んでみましょう。');const c=byId.get(flash.ids[flash.index]);return `<div class="flash-wrap">${head('単語カード',flash.review?'復習が必要な単語を集めました。':'表で思い出し、裏で確かめよう。')}<div class="flash-meta"><span>${flash.index+1} / ${flash.ids.length}語</span><span class="subtle">今回 ${flash.done}語を確認</span></div>${!flash.flipped?`<button class="flash-card" data-action="flip" aria-label="${e(c.term)}の答えを見る"><span class="eyebrow">この科目、どんなときに使う？</span><div class="flash-term">${e(c.term)}</div><span class="subtle">意味・分類・借方と貸方を思い出そう</span><span class="flash-hint">タップして答えを見る ${icon('repeat')}</span></button>`:`<section class="flash-card flash-back"><h2 class="flash-term">${e(c.term)}</h2><div class="answer-tags">${tags(c)}</div><p class="meaning">${e(c.meaning)}</p>${c.example?`<div class="example"><strong>使う場面</strong>${e(c.example)}</div>`:''}${c.aliases?.length?`<p class="tiny-note">別名・関連表記：${e(c.aliases.join('、'))}</p>`:''}${c.notes?`<p class="tiny-note">${e(c.notes)}</p>`:''}</section>`}<div class="flash-actions">${flash.flipped?(c.quizEligible===false?button('次の単語へ','flash-next','primary'):`${button('もう一度覚える','rate-again','danger-soft')}${button(`${icon('check')} 覚えていた`,'rate-good','soft')}`):button('答えを見る','flip','primary')}</div><div class="flash-nav">${button(`${icon('back')} 前の単語`,'flash-prev','text-button',flash.index===0?'disabled':'')}${button('次の単語 '+icon('chevron'),'flash-next','text-button')}</div><p class="tiny-note">「覚えていた」は次の復習までの間隔が延びます。「もう一度覚える」は苦手の復習に追加されます。</p></div>`;}
function reviewView(){const list=reviewCards(),weak=list.filter(c=>C.weak(state.stats[c.id]));return head('苦手の復習','間違えた単語と、復習のタイミングが来た単語。')+(list.length?`<section class="panel"><div class="section-title"><div><h2>${list.length}語を、もう一度。</h2><p class="subtle">苦手 ${weak.length}語 · ${list.length-weak.length}語は復習のタイミング</p></div><span class="tag orange">REVIEW</span></div><div class="button-row">${button('クイズで復習','review-start')}${button('カードで復習','review-cards','secondary')}</div><p class="tiny-note">2回続けてできた単語は苦手から外れます。時間を空けて、また確かめましょう。</p></section><div class="weak-list">${list.map(c=>`<article class="panel weak-item"><div><h3>${e(c.term)}</h3><p>${C.weak(state.stats[c.id])?'もう一度覚えたい単語':'前回の学習から時間が空きました'}</p></div>${button('確認する','open-card','text-button',`data-id="${c.id}"`)}</article>`).join('')}</div>`:empty('いま復習する単語はありません','間違えた単語はここに集まります。まずは10問、気軽に試してみましょう。'));}
function filteredWords(){let needle=search.normalize('NFKC').toLowerCase();return selectedCards().filter(c=>(category==='all'||c.category===category)&&(!needle||[c.term,c.meaning,...(c.aliases||[])].join(' ').normalize('NFKC').toLowerCase().includes(needle)));}
function wordResults(){const list=filteredWords();return `<div class="section-title"><span class="subtle">${list.length}語</span><span class="subtle">参考科目はクイズに出題しません</span></div><div class="word-grid">${list.map(c=>`<article class="panel word-item"><div class="word-top"><h3>${e(c.term)}</h3>${c.quizEligible===false?'<span class="tag gray">参考</span>':badge(c)}</div><p>${e(c.meaning)}</p><div class="word-top"><span class="tag">${e(c.category)}</span>${button('詳しく見る','detail','',`data-id="${c.id}"`)}</div></article>`).join('')}</div>${!list.length?'<div class="panel empty"><h2>一致する単語がありません</h2><p>別の言葉や分類で探してみてください。</p></div>':''}`;}
function dictionary(){return head('単語一覧','意味や別名からも探せます。')+`<div class="dictionary-controls"><label class="searchbox">${icon('search')}<span class="sr-only">単語を検索</span><input id="word-search" type="search" placeholder="勘定科目・意味で検索" value="${e(search)}" autocomplete="off"></label><label><span class="sr-only">分類を選ぶ</span><select id="category"><option value="all">すべての分類</option>${['資産','負債','純資産','収益','費用','評価勘定','集計','その他'].map(v=>`<option ${category===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div id="word-results">${wordResults()}</div>`;}
function results(){if(!result)return home();let correct=result.results.filter(x=>x.correct).length;return `<div class="quiz-wrap">${head('おつかれさまでした。','思い出した回数が、次の一歩に。')}<section class="panel results-top"><span class="tag blue">${gradeName(result.grade)} · ${result.mode==='review'?'復習':'今日の10問'}</span><div class="result-score">${correct}<span>/ ${result.results.length}問 正解</span></div><p>${correct===result.results.length?'全問正解！ 時間を空けて、また確かめましょう。':`間違えた${result.results.length-correct}語は「苦手の復習」に保存しました。`}</p><div class="button-row fill" style="justify-content:center">${button('今日の学習へ','nav','primary','data-view="home"')}${button('苦手を確認する','nav','secondary','data-view="review"')}</div></section><div class="result-list">${result.results.map(r=>`<div class="result-row ${r.correct?'':'miss'}">${icon(r.correct?'check':'close')}<span>${e(byId.get(r.cardId)?.term)}</span>${button('意味を見る','detail','',`data-id="${r.cardId}"`)}</div>`).join('')}</div></div>`;}
function render(focus=false){app.innerHTML=shell(({home,cards:cardsView,review:reviewView,dictionary,quiz,results}[view]||home)());if(focus)document.querySelector('h1')?.focus({preventScroll:true});}
function changeView(v){if(!['home','cards','review','dictionary'].includes(v))return;if(v==='cards'&&!flash.ids.length)initFlash();view=v;render(true);window.scrollTo(0,0);}
function startQuiz(mode='daily'){let s=state.sessions[state.grade];if(s&&s.mode!==mode){if(!window.confirm('途中のクイズを終了して、新しいクイズを始めますか？ 回答済みの学習記録は残ります。'))return;s=null;}
 if(!s){const questions=C.makeQuestions(data,state,state.grade,mode);if(!questions.length){view='review';render(true);return;}s={grade:state.grade,mode,questions,index:0,selected:null,results:[]};state.sessions[state.grade]=s;save();}view='quiz';render(true);window.scrollTo(0,0);}
function showDialog(title,body){const d=document.querySelector('#dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button(icon('close'),'close','close','aria-label="閉じる"')}</div>${body}`;d.showModal();}
function detail(id){const c=byId.get(id);if(!c)return;showDialog(e(c.term),`<div class="answer-tags">${tags(c)}</div><div class="dialog-text"><p>${e(c.meaning)}</p>${c.example?`<div class="example"><strong>使う場面</strong>${e(c.example)}</div>`:''}${c.aliases?.length?`<p class="tiny-note">別名・関連表記：${e(c.aliases.join('、'))}</p>`:''}${c.notes?`<p class="tiny-note">${e(c.notes)}</p>`:''}<p class="tiny-note">勘定科目の指定がある場合は、問題文に従ってください。</p></div>`);}
function about(){showDialog('簿記ことばの使い方',`<div class="dialog-text"><p><strong>今日の10問</strong>で分類・借方と貸方・取引を練習。<strong>単語カード</strong>で意味を確かめ、<strong>苦手の復習</strong>で覚え直します。</p><p>できた単語は1日・3日・7日・14日・30日と復習の間隔が延びます。間違えた単語は苦手に入り、2回続けてできると苦手から外れます。3回続けてできた単語を「定着」と表示します。</p><p>1日の目標はクイズ10問です。カード学習は別に記録されます。続けて学習した日数は、クイズとカードの両方が対象です。</p><p><strong>記録はこのブラウザに保存</strong>されます。端末・ブラウザ間の同期はありません。ブラウザのデータ削除やプライベートモードでは記録を残せない場合があります。個人の学習記録を外部へ送信しません。</p><p>2026年度学習用。前に作成した勘定科目一覧表を基に、一語ずつの説明と学習問題を編集しています。2級では3級の基本科目も扱います。出題範囲が限定される科目は「参考」としてクイズから外しています。</p><p>日本商工会議所の公式アプリではありません。試験では問題文の科目指定が優先されます。2027年度以降に受験する場合は、改定後の出題範囲を確認してください。</p><ul class="about-sources"><li><a href="https://www.kentei.ne.jp/bookkeeping/35697-2" target="_blank" rel="noopener noreferrer">日本商工会議所 出題区分表</a></li><li><a href="https://www.kentei.ne.jp/wp/wp-content/uploads/2021/12/2022_kamoku.pdf" target="_blank" rel="noopener noreferrer">標準・許容勘定科目表（2022年度版）</a></li><li><a href="https://www.kentei.ne.jp/bookkeeping/sample/sample-two" target="_blank" rel="noopener noreferrer">2級サンプル問題</a></li></ul></div>`);}
function syncSaved(){try{const saved=localStorage.getItem(KEY);if(saved){const grade=state.grade;state=C.clean(JSON.parse(saved),new Set(byId.keys()));state.grade=grade;}}catch{}}
function handleAction(b){const a=b.dataset.action;
if(a==='nav'){changeView(b.dataset.view);return;}
if(a==='grade'){if(view==='quiz')return;state.grade=b.dataset.grade;flash.ids=[];search='';category='all';if(view==='cards')initFlash();if(view==='results')view='home';save();render();return;}
if(a==='quiz-start'){startQuiz();return;}if(a==='review-start'){startQuiz('review');return;}
if(a==='answer'){const session=state.sessions[state.grade];if(!session||session.index!==Number(b.dataset.index)||session.questions[session.index].cardId!==b.dataset.card){render();return;}if(C.answerSession(state,state.grade,Number(b.dataset.choice))){save();render();document.querySelector('[data-action="next-question"]')?.scrollIntoView({block:'nearest',behavior:'auto'});document.querySelector('[data-action="next-question"]')?.focus({preventScroll:true});}return;}
if(a==='next-question'){const s=state.sessions[state.grade];if(!s||s.selected===null||s.index!==Number(b.dataset.index)){render();return;}if(s.index===s.questions.length-1){result=JSON.parse(JSON.stringify(s));delete state.sessions[state.grade];view='results';}else{s.index++;s.selected=null;}save();render(true);window.scrollTo(0,0);return;}
if(a==='open-card'){initFlash(b.dataset.id);render(true);window.scrollTo(0,0);return;}
if(a==='review-cards'){initFlash(null,true);render(true);return;}
if(a==='flip'){flash.flipped=true;render();return;}
if(a==='flash-prev'){flash.index=Math.max(0,flash.index-1);flash.flipped=false;render();document.querySelector('.flash-card')?.scrollIntoView({block:'start',behavior:'auto'});document.querySelector('.flash-card')?.focus({preventScroll:true});return;}
if(['rate-good','rate-again','flash-next'].includes(a)){
 if(a!=='flash-next'){if(!flash.flipped)return;const c=byId.get(flash.ids[flash.index]);if(c?.quizEligible!==false){C.record(state,c.id,a==='rate-good','card');save();}flash.done++;}
 flash.index=(flash.index+1)%flash.ids.length;flash.flipped=false;render();document.querySelector('.flash-card')?.scrollIntoView({block:'start',behavior:'auto'});document.querySelector('.flash-card')?.focus({preventScroll:true});return;
}
if(a==='detail'){detail(b.dataset.id);return;}if(a==='about'){about();return;}if(a==='close'){document.querySelector('#dialog').close();return;}
if(a==='all-confusions'){const pairs=data.confusions.filter(p=>p.terms.every(id=>byId.has(id)&&C.inGrade(byId.get(id),state.grade)));showDialog('似ている科目の使い分け',`<div class="dialog-pair">${pairs.map(p=>`<article><h3>${p.terms.map(id=>e(byId.get(id).term)).join(' / ')}</h3><p>${e(p.tip)}</p></article>`).join('')||'<p>この範囲の使い分けは、単語カードの具体例で確認できます。</p>'}</div>`);return;}
if(a==='confusion'){const p=data.confusions[Number(b.dataset.index)];if(!p)return;showDialog('似ている科目の使い分け',`<div class="dialog-pair">${p.terms.map(id=>{const c=byId.get(id);return `<article><h3>${e(c.term)}</h3><p>${e(c.meaning)}</p><div class="example">${e(c.example)}</div></article>`;}).join('')}</div><p class="example">${e(p.tip)}</p>`);}
}
app.addEventListener('click',async ev=>{
 const b=ev.target.closest('button[data-action]');if(!b||b.disabled)return;
 const mutating=['grade','quiz-start','review-start','answer','next-question','rate-good','rate-again'].includes(b.dataset.action);
 const run=()=>{if(mutating)syncSaved();handleAction(b);};
 if(mutating&&navigator.locks?.request){await navigator.locks.request('boki-kotoba-state',run);}else run();
});
app.addEventListener('input',ev=>{if(ev.target.id==='word-search'){search=ev.target.value;document.querySelector('#word-results').innerHTML=wordResults();}});
app.addEventListener('change',ev=>{if(ev.target.id==='category'){category=ev.target.value;document.querySelector('#word-results').innerHTML=wordResults();}});
window.addEventListener('storage',ev=>{if(ev.key===KEY){try{const grade=state.grade;state=C.clean(JSON.parse(ev.newValue),new Set(byId.keys()));state.grade=grade;if(view==='quiz'&&!state.sessions[grade])view='home';render();}catch{}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&shownDate!==C.dayKey()){shownDate=C.dayKey();if(view==='home'||view==='review')render();}});
render();
// Expose the same view navigation and visible progress to supported browser agents.
if(document.modelContext?.registerTool){const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});
const tool={name:'read_learning_progress',title:'学習状況を確認',description:'現在選択中の級の学習状況を読み取ります。回答や記録の変更は行いません。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('入力は空のオブジェクトにしてください。');const cards=activeCards();return {grade:gradeName(),total:cards.length,studied:cards.filter(c=>state.stats[c.id]?.seen).length,mastered:cards.filter(c=>C.mastered(state.stats[c.id])).length,review:reviewCards().length,today:state.days[C.dayKey()]||{answered:0,correct:0,cards:0}};}};
try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}
}
})();
